import org.springframework.boot.SpringApplication; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.context.ApplicationContext; import org.springframework.data.mongodb.core.MongoTemplate; @SpringBootApplication public class DbCheck { public static void main(String[] args) { ApplicationContext ctx = SpringApplication.run(DbCheck.class, args); MongoTemplate mt = ctx.getBean(MongoTemplate.class); System.out.println("--- DEMANDA SAMPLE ---"); System.out.println(mt.getCollection("demandas").find().first().toJson()); System.exit(0); } }
